llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Baricitinib, a high-transfer kinase-inhibitor analogue with a heteroaromatic core and basic amine, has an absolute oral bioavailability of 80% in healthy volunteers, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Vilazodone, which shares an aryl piperazine and indole motif with the query, has an absolute oral bioavailability of 72% in humans with food, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LSD, an indole-containing CNS-active drug, has an absolute oral bioavailability of 80% in healthy participants, supporting high F for the similarly indole-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Belumosudil, an indazole-containing kinase inhibitor, has an absolute oral bioavailability of 64% after a 200 mg oral dose in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Golidocitinib, a structurally similar indazole/piperazine kinase inhibitor, was concluded to have >80% oral bioavailability in humans from a mass-balance study, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Brexpiprazole, an aryl piperazine with fused heteroaromatic rings, has 95% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Abecarnil, an indole-containing drug, has absolute oral bioavailability 39±17% (range 23-70%) in healthy volunteers, still above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Bromerguride, an indole ergoline analogue, has 25% absolute oral bioavailability at 2 mg in healthy volunteers, the lowest among the analogues but still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show human absolute oral bioavailability values of 25% or higher, with most in the 64-95% range, consistently above the 20% threshold. The query's heteroaromatic/piperazine scaffold closely resembles these well-absorbed drugs, supporting a high F prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "Some analogues show lower bioavailability (e.g., bromerguride 25%, abecarnil variable 23-70%), but none fall below the 20% threshold.",
    "Food effects and formulation dependence are noted for some analogues, but the query's predicted high F is not undermined by these observations."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

